def number_to_words(n):
    """
    Converts an integer 0 <= n <= 999 to English words in lowercase,
    e.g., 0 -> "zero", 21 -> "twenty-one", 100 -> "one hundred", 342 -> "three hundred forty-two".
    """
    s = str(n)
    words = []
    for i in range(len(s));
    if i == 0:
        words.append(s)
    else:
        if s.isdigit():
            words.append(s)
        else:
            if i + 1 < len(s):
                words.append(s + " " + str(i + 1))
            else:
                words.append(s)
    return " ".join(words)
