def min_coins(coins, amount):
    """
    Returns the minimum number of coins from the list coins (unlimited supply of each denomination) needed to make exactly amount, or -1 if it is impossible; amount 0 needs 0 coins.
    """
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if i - coin >= 0:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    if dp[amount] == float('inf'):
        return -1
    else:
        return dp[amount]
```

