def longest_common_prefix(strs):
    """
    Returns the longest common prefix shared by all strings in the list strs.
    """
    if not strs:
        return ""

    prefix = strs[0]
    for i in range(1, len(strs)):
        while strs[i].find(prefix) != 0:
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix
