    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
    result = []

    # Process hundreds
    if n >= 100:
        result.append(hundreds[0])
        n -= 100

    # Process tens
    if n >= 20:
        result.append(tens[n // 10])
        n %= 10

    # Process ones
    if n > 0:
        result.append(digits[n])

    return ''.join(result)

def edit_distance(a, b):
    if not a:
        return len(b)
    if not b:
        return len(a)

    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]

    for i in range(len(a) + 1):
        dp[i][0] = i
    for j in range(len(b) + 1):
        dp[0][j] = j

    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])

    return dp[len(a)][len(b)]

def longest_word(s):
    words = s.split()
    if not words:
        return ""
    return max(words)

def min_coins(coins, amount):
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Initialize a list to store the minimum coins needed for each amount up to 'amount'
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1

def lcs_length(a, b):
    if not a or not b:
        return 0
    if a == b:
        return len(a)
    if a[0] == b[0]:
        return 1 + lcs_length(a[1:], b[1:])
    return max(lcs_length(a[1:], b), lcs_length(a, b[1:]))

def longest_unique_substring(s):
    if not s:
        return 0

    seen = set()
    start = 0
    max_len = 0

    for end in range(len(s)):
        if s[end] in seen:
            while s[end] in seen:
                seen.remove(s[start])
                start += 1
        seen.add(s[end])
        max_len = max(max_len, end - start + 1)

    return max_len

def is_sorted(xs):
    if not xs:
        return True
    if len(xs) == 1:
        return True
    return xs <= xs[1]

def longest_common_prefix(strs):
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        i = 0
        while i < len(prefix) and i < len(s) and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
        if not prefix:
            break
    return prefix

def max_subarray_sum(nums):
    if not nums:
        return 0
    max_current = max_global = nums[0]
    for num in nums[1:]:
        max_current = max(num, max_current + num)
        max_global = max(max_global, max_current)
    return max_global

def to_base(n, b):
    if n == 0:
        return "0"
    digits = "0123456789ABCDEF"
    sign = "-" if n < 0 else ""
    n = abs(n)
    result = []
    while n > 0:
        result.append(digits[n % b])
        n = n // b
    return sign + ''.join(reversed(result))

def repeat_with_dash(s, n):
    if n <= 0:
        return ""
    result = []
    for i in range(n):
        result.append(s)
        if i < n - 1:
            result.append("-")
    return "".join(result)

def two_sum(nums, target):
    num_map = {}
    for i, num in enumerate(nums):
        if num in num_map:
            j = num_map[num]
            if j < i:
                return [j, i]
        num_map[num] = i
    return None

def swap_pairs(xs):
    result = []
    i = 0
    while i < len(xs):
        result.append(xs[i])
        if i + 1 < len(xs):
            result.append(xs[i + 1])
            i += 2
        else:
            i += 1
    return result

def pascal_row(n):
    if n < 0:
        return []
    if n == 0:
        return [1]
    row = [1]
    for i in range(1, n):
        row.append((row[i-1] + row[i]) // 1)
    return row

def product_of_list(xs):
    if not xs:
        return 1
    result = 1
    for num in xs:
        result *= num
    return result
